function getConfig(key, def) {
  try {
    if (typeof config !== 'undefined' && config && config[key] != null) return config[key];
    if (typeof userConfig !== 'undefined' && userConfig && userConfig[key] != null) return userConfig[key];
  } catch (e) {}
  return def;
}
function tmdbLang() { return getConfig('tmdb_lang', 'es-ES') || 'es-ES'; }
function enabledSections() {
  return String(getConfig('enabled_sections', 'Discover,Franchises,Genres Movies,Genres TV,Decades,Directors,Productoras,Premios'))
    .split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean);
}
function hiddenCatalogs() {
  return String(getConfig('hide_catalogs', '')).split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean);
}
function getEnabledSources() {
  var raw = getConfig('enabled_sources', 'embed69,vimeus,lamovie,elifilms,homecine');
  return String(raw).toLowerCase().split(/[,;\s]+/).map(function (s) { return s.trim(); }).filter(Boolean);
}
function getMaxConcurrent() {
  var n = parseInt(getConfig('max_concurrent_sources', '3'), 10);
  return Math.max(1, Math.min(5, isNaN(n) ? 3 : n));
}

async function tmdbFetch(path, params) {
  params = params || {};
  var qs = ['api_key=' + encodeURIComponent(TMDB_KEY), 'language=' + encodeURIComponent(tmdbLang())];
  for (var k in params) {
    if (params[k] != null && params[k] !== '') qs.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(params[k])));
  }
  var res = await fetch(TMDB_BASE + path + '?' + qs.join('&'));
  if (!res.ok) throw new Error('TMDB ' + res.status);
  return res.json();
}

function posterUrl(path, size) {
  size = size || 'w342';
  if (!path) return null;
  if (String(path).indexOf('http') === 0) return path;
  return IMG_BASE + '/' + size + path;
}
function backdropUrl(path, size) {
  size = size || 'w780';
  if (!path) return null;
  if (String(path).indexOf('http') === 0) return path;
  return IMG_BASE + '/' + size + path;
}

function mapTmdbItem(item, typeHint) {
  var isTv = typeHint === 'tv' || typeHint === 'series' || item.media_type === 'tv' ||
    (!!item.first_air_date && !item.release_date);
  var type = isTv ? 'tv' : 'movie';
  var tid = String(item.id);
  var title = item.title || item.name || item.original_title || item.original_name || 'Sin título';
  var year = ((item.release_date || item.first_air_date || '') + '').slice(0, 4) || null;
  return {
    id: type + ':' + tid,
    tmdbId: tid,
    imdbId: item.imdb_id || null,
    title: title,
    name: title,
    poster: posterUrl(item.poster_path),
    backdrop: backdropUrl(item.backdrop_path),
    overview: item.overview || '',
    description: item.overview || '',
    type: type,
    media_type: type,
    rating: item.vote_average || null,
    year: year,
    genres: (item.genre_ids || []).map(String)
  };
}

function parseContentId(id) {
  var raw = String(id || '').trim();
  var tmdbId = raw, type = 'movie';
  function normType(t) {
    t = String(t || 'movie').toLowerCase();
    if (t === 'series' || t === 'show' || t === 'tv') return 'tv';
    return 'movie';
  }
  if (raw.charAt(0) === '{') {
    try {
      var j = JSON.parse(raw);
      tmdbId = String(j.tmdbId || j.id || j.tmdb || raw);
      type = normType(j.type || j.media_type || 'movie');
      return { tmdbId: tmdbId, type: type, mediaType: type === 'tv' ? 'tv' : 'movie' };
    } catch (e) {}
  }
  var m = raw.match(/^(movie|series|tv|show)[:\/](\d+)/i);
  if (m) return { tmdbId: m[2], type: normType(m[1]), mediaType: normType(m[1]) === 'tv' ? 'tv' : 'movie' };
  m = raw.match(/^(\d+)[:\/](movie|series|tv|show)/i);
  if (m) return { tmdbId: m[1], type: normType(m[2]), mediaType: normType(m[2]) === 'tv' ? 'tv' : 'movie' };
  if (/^\d+$/.test(raw)) tmdbId = raw;
  return { tmdbId: tmdbId, type: 'movie', mediaType: 'movie' };
}

function loadCatalogs() {
  return (typeof CATALOGS_DATA !== 'undefined' && CATALOGS_DATA) ? CATALOGS_DATA : [];
}

function findFolder(catalogId) {
  var cid = String(catalogId || '').trim();
  var sections = loadCatalogs();
  for (var i = 0; i < sections.length; i++) {
    var sec = sections[i];
    var folders = sec.folders || [];
    for (var j = 0; j < folders.length; j++) {
      var f = folders[j];
      var fid = String(f.id || '').trim();
      var ftitle = String(f.title || '').trim();
      if (fid === cid || ftitle === cid || fid.toLowerCase() === cid.toLowerCase() || ftitle.toLowerCase() === cid.toLowerCase()) {
        return { folder: f, sectionTitle: sec.title || '', section: sec };
      }
    }
  }
  return { folder: null, sectionTitle: '', section: null };
}

// ─── Home: solo lista de catálogos por sesión ──────────────────────────────

async function getHome() {
  var sections = loadCatalogs();
  var enabled = enabledSections();
  var hidden = hiddenCatalogs();
  var skipSections = { 'streaming services': true, 'streaming': true }; // Premios, Productoras, Genres TV activos
  var rows = [];
  for (var i = 0; i < sections.length; i++) {
    var sec = sections[i];
    var stitle = (sec.title || '').replace(/\u200e/g, '').trim();
    var st = stitle.toLowerCase();
    if (skipSections[st]) continue;
    if (enabled.length && enabled.indexOf(st) === -1) continue;
    var items = [];
    var folders = sec.folders || [];
    for (var j = 0; j < folders.length; j++) {
      var folder = folders[j];
      var t = (folder.title || '').toLowerCase();
      var id = (folder.id || '').toLowerCase();
      var skip = false;
      for (var h = 0; h < hidden.length; h++) {
        if (t.indexOf(hidden[h]) !== -1 || id.indexOf(hidden[h]) !== -1) { skip = true; break; }
      }
      if (skip) continue;
      var catId = String(folder.id || folder.title);
      items.push({
        id: catId,
        title: folder.title,
        name: folder.title,
        poster: folder.cover || null,
        backdrop: folder.cover || null,
        type: 'catalog',
        overview: 'Catálogo: ' + folder.title,
        catalogId: catId
      });
    }
    if (items.length) {
      rows.push({ id: String(sec.id || stitle), title: stitle, type: 'row', imageStyle: 'backdrop', items: items });
    }
  }
  return { rows: rows };
}

async function getCatalogs() {
  var home = await getHome();
  var list = [];
  (home.rows || []).forEach(function (row) {
    (row.items || []).forEach(function (it) {
      list.push({ id: it.id, title: row.title + ' › ' + it.title, poster: it.poster, backdrop: it.backdrop, description: it.overview });
    });
  });
  return { catalogs: list };
}


