/**
 * Contenido REAL según el catálogo (título + sources del JSON).
 */
async function fetchCatalogContent(folder, page) {
  page = String(page || 1);
  var title = (folder.title || '').toLowerCase().trim();
  var section = '';
  // section se pasa opcionalmente
  var sources = folder.sources || [];
  var preferTv = false;
  var preferMovie = false;
  for (var i = 0; i < sources.length; i++) {
    if (sources[i].type === 'series' || sources[i].type === 'tv') preferTv = true;
    if (sources[i].type === 'movie') preferMovie = true;
  }

  // ── DISCOVER / TRENDING / POPULAR ──
  if (/trending\s*show|trending\s*tv|shows?\s*trending/i.test(title) || title === 'trending shows') {
    var d = await tmdbFetch('/trending/tv/week', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'tv'); });
  }
  if (/trending\s*movie/i.test(title) || title === 'trending movies') {
    var d = await tmdbFetch('/trending/movie/week', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'movie'); });
  }
  if (/popular\s*show/i.test(title) || title === 'popular shows') {
    var d = await tmdbFetch('/tv/popular', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'tv'); });
  }
  if (/popular\s*movie/i.test(title) || title === 'popular movies') {
    var d = await tmdbFetch('/movie/popular', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'movie'); });
  }
  if (/top\s*rated\s*show|best\s*rated\s*show/i.test(title)) {
    var d = await tmdbFetch('/tv/top_rated', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'tv'); });
  }
  if (/top\s*rated\s*movie|best\s*rated\s*movie/i.test(title)) {
    var d = await tmdbFetch('/movie/top_rated', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'movie'); });
  }
  if (/now\s*playing|en\s*cartelera/i.test(title)) {
    var d = await tmdbFetch('/movie/now_playing', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'movie'); });
  }
  if (/upcoming|próximamente|proximamente/i.test(title)) {
    var d = await tmdbFetch('/movie/upcoming', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'movie'); });
  }
  if (/airing|on\s*the\s*air|al\s*aire/i.test(title)) {
    var d = await tmdbFetch('/tv/on_the_air', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, 'tv'); });
  }
  if (/trending/i.test(title) && !/movie|show|tv/i.test(title)) {
    var d = await tmdbFetch('/trending/all/week', { page: page });
    return (d.results || []).map(function (r) { return mapTmdbItem(r, r.media_type); });
  }

  // ── FRANQUICIAS → collection TMDB ──
  var collectionId = null;
  for (var fname in FRANCHISE_COLLECTIONS) {
    if (title.indexOf(fname) !== -1 || fname.indexOf(title) !== -1) {
      collectionId = FRANCHISE_COLLECTIONS[fname];
      break;
    }
  }
  if (collectionId === 0 && /marvel/i.test(title)) {
    // Marvel: buscar colección o discover keyword
    try {
      var sc = await tmdbFetch('/search/collection', { query: 'Marvel' });
      if (sc.results && sc.results[0]) collectionId = sc.results[0].id;
    } catch (e) {}
  }
  if (!collectionId && folder._section === 'Franchises') {
    try {
      var sc2 = await tmdbFetch('/search/collection', { query: folder.title });
      if (sc2.results && sc2.results[0]) collectionId = sc2.results[0].id;
    } catch (e) {}
  }
  if (collectionId) {
    try {
      var col = await tmdbFetch('/collection/' + collectionId);
      var parts = col.parts || [];
      // paginar manual
      var start = (parseInt(page, 10) - 1) * 20;
      var slice = parts.slice(start, start + 20);
      return slice.map(function (r) { return mapTmdbItem(r, 'movie'); });
    } catch (e) {}
  }

  // ── DIRECTORES → person id + credits ──
  var personId = null;
  for (var dname in DIRECTOR_IDS) {
    if (title.indexOf(dname) !== -1 || dname.indexOf(title) !== -1) {
      personId = DIRECTOR_IDS[dname];
      break;
    }
  }
  if (!personId && folder._section === 'Directors') {
    try {
      var sp = await tmdbFetch('/search/person', { query: folder.title });
      if (sp.results && sp.results[0]) personId = sp.results[0].id;
    } catch (e) {}
  }
  if (personId) {
    try {
      var credits = await tmdbFetch('/person/' + personId + '/combined_credits');
      var crew = credits.crew || [];
      var directed = crew.filter(function (c) {
        return (c.job === 'Director' || c.job === 'director');
      });
      // unique by id
      var seen = {};
      var list = [];
      for (var i = 0; i < directed.length; i++) {
        var c = directed[i];
        if (seen[c.id]) continue;
        seen[c.id] = true;
        list.push(c);
      }
      // sort by popularity / date
      list.sort(function (a, b) {
        return (b.popularity || 0) - (a.popularity || 0);
      });
      var start = (parseInt(page, 10) - 1) * 20;
      var slice = list.slice(start, start + 20);
      return slice.map(function (r) {
        return mapTmdbItem(r, r.media_type === 'tv' ? 'tv' : 'movie');
      });
    } catch (e) {}
  }


  // ── PRODUCTORAS / STUDIOS ──
  var companyId = null;
  if (folder.companyId) companyId = folder.companyId;
  if (!companyId) {
    for (var sname in STUDIO_IDS) {
      if (title === sname || title.indexOf(sname) !== -1 || sname.indexOf(title) !== -1) {
        companyId = STUDIO_IDS[sname];
        break;
      }
    }
  }
  // desde sources catalogId tmdb.company.ID
  if (!companyId) {
    for (var si = 0; si < sources.length; si++) {
      var cm = String(sources[si].catalogId || '').match(/tmdb\.company\.(\d+)/i);
      if (cm) { companyId = parseInt(cm[1], 10); break; }
    }
  }
  if (companyId) {
    var itemsCo = [];
    try {
      var dco = await tmdbFetch('/discover/movie', {
        page: page,
        with_companies: String(companyId),
        sort_by: 'popularity.desc'
      });
      (dco.results || []).forEach(function (r) { itemsCo.push(mapTmdbItem(r, 'movie')); });
    } catch (e) {}
    try {
      var dcot = await tmdbFetch('/discover/tv', {
        page: page,
        with_companies: String(companyId),
        sort_by: 'popularity.desc'
      });
      (dcot.results || []).forEach(function (r) { itemsCo.push(mapTmdbItem(r, 'tv')); });
    } catch (e) {}
    if (itemsCo.length) return itemsCo;
  }

  // ── PREMIOS ──
  var awardKey = folder.awardKey || '';
  if (!awardKey) {
    for (var ai = 0; ai < sources.length; ai++) {
      var am = String(sources[ai].catalogId || '').match(/tmdb\.award\.(\w+)/i);
      if (am) { awardKey = am[1]; break; }
    }
  }
  if (!awardKey) {
    if (/oscar/i.test(title)) awardKey = 'oscar';
    else if (/emmy/i.test(title)) awardKey = 'emmy';
    else if (/golden\s*globe/i.test(title)) awardKey = 'golden_globe';
    else if (/cannes|palme/i.test(title)) awardKey = 'cannes';
    else if (/bafta/i.test(title)) awardKey = 'bafta';
    else if (/highly\s*rated|8\+/i.test(title)) awardKey = 'high_rated';
    else if (/critical|acclaimed/i.test(title)) awardKey = 'critical';
  }
  if (awardKey) {
    // TMDB: keyword search + high ratings (no endpoint oficial de premios)
    var awardQuery = {
      oscar: 'Oscar',
      oscar_winners: 'Academy Award',
      emmy: 'Emmy',
      golden_globe: 'Golden Globe',
      cannes: 'Cannes',
      bafta: 'BAFTA',
      high_rated: null,
      critical: null
    };
    var itemsAw = [];
    if (awardKey === 'high_rated' || awardKey === 'critical') {
      var dhr = await tmdbFetch('/discover/movie', {
        page: page,
        sort_by: 'vote_average.desc',
        'vote_count.gte': awardKey === 'critical' ? 500 : 1000,
        'vote_average.gte': awardKey === 'high_rated' ? 8 : 7.5
      });
      (dhr.results || []).forEach(function (r) { itemsAw.push(mapTmdbItem(r, 'movie')); });
      var dhrt = await tmdbFetch('/discover/tv', {
        page: page,
        sort_by: 'vote_average.desc',
        'vote_count.gte': 200,
        'vote_average.gte': 8
      });
      (dhrt.results || []).forEach(function (r) { itemsAw.push(mapTmdbItem(r, 'tv')); });
    } else {
      var q = awardQuery[awardKey] || title;
      try {
        var sk = await tmdbFetch('/search/keyword', { query: q });
        var kid = (sk.results && sk.results[0] && sk.results[0].id) || null;
        if (kid) {
          var dkw = await tmdbFetch('/discover/movie', {
            page: page,
            with_keywords: String(kid),
            sort_by: 'popularity.desc'
          });
          (dkw.results || []).forEach(function (r) { itemsAw.push(mapTmdbItem(r, 'movie')); });
        }
      } catch (e) {}
      if (!itemsAw.length) {
        // fallback: buscar por texto
        var sm = await tmdbFetch('/search/movie', { query: q, page: page });
        (sm.results || []).forEach(function (r) { itemsAw.push(mapTmdbItem(r, 'movie')); });
      }
    }
    if (itemsAw.length) return itemsAw;
  }

  // ── GÉNEROS TV (sesión Genres TV) ──
  if (folder._section === 'Genres TV' || (sources[0] && String(sources[0].catalogId || '').indexOf('tmdb.tv.genre') === 0)) {
    for (var tg in TV_GENRE_MAP) {
      if (title === tg || title.indexOf(tg) !== -1 || tg.indexOf(title) !== -1) {
        var tgid = TV_GENRE_MAP[tg];
        var dtv = await tmdbFetch('/discover/tv', {
          page: page,
          with_genres: String(tgid),
          sort_by: 'popularity.desc'
        });
        return (dtv.results || []).map(function (r) { return mapTmdbItem(r, 'tv'); });
      }
    }
    // match by catalogId
    for (var si2 = 0; si2 < sources.length; si2++) {
      var tgm = String(sources[si2].catalogId || '').match(/tmdb\.tv\.genre\.(.+)/i);
      if (tgm) {
        var key = tgm[1].replace(/_/g, ' ').toLowerCase();
        var idg = TV_GENRE_MAP[key];
        if (idg) {
          var dtv2 = await tmdbFetch('/discover/tv', { page: page, with_genres: String(idg), sort_by: 'popularity.desc' });
          return (dtv2.results || []).map(function (r) { return mapTmdbItem(r, 'tv'); });
        }
      }
    }
  }

  // ── GÉNEROS MOVIES (sesión Genres Movies) ──

  // ── GÉNEROS MOVIES ──
  if (folder._section === 'Genres Movies' || folder._section === 'Genres' || !folder._section) {
    for (var g in GENRE_MAP) {
      if (title === g || title.indexOf(g) !== -1) {
        var gid = GENRE_MAP[g];
        var dm = await tmdbFetch('/discover/movie', { page: page, with_genres: String(gid), sort_by: 'popularity.desc' });
        return (dm.results || []).map(function (r) { return mapTmdbItem(r, 'movie'); });
      }
    }
  }

  // ── DÉCADAS: movie + tv ──
  var dec = title.match(/(1980|1990|2000|2010|2020)s?/);
  if (dec) {
    var y = parseInt(dec[1], 10);
    var items = [];
    try {
      var dm = await tmdbFetch('/discover/movie', {
        page: page,
        'primary_release_date.gte': y + '-01-01',
        'primary_release_date.lte': (y + 9) + '-12-31',
        sort_by: 'popularity.desc'
      });
      (dm.results || []).forEach(function (r) { items.push(mapTmdbItem(r, 'movie')); });
    } catch (e) {}
    try {
      var dt = await tmdbFetch('/discover/tv', {
        page: page,
        'first_air_date.gte': y + '-01-01',
        'first_air_date.lte': (y + 9) + '-12-31',
        sort_by: 'popularity.desc'
      });
      (dt.results || []).forEach(function (r) { items.push(mapTmdbItem(r, 'tv')); });
    } catch (e) {}
    return items;
  }

  // ── Sources del JSON (tmdb.discover explícito) ──
  for (var s = 0; s < sources.length; s++) {
    var cid = String(sources[s].catalogId || '').toLowerCase();
    var mt = (sources[s].type === 'series' || sources[s].type === 'tv') ? 'tv' : 'movie';
    if (cid.indexOf('tmdb.discover') !== -1 || cid.indexOf('trending') !== -1) {
      if (cid.indexOf('trending') !== -1) {
        var path = '/trending/' + (mt === 'tv' || cid.indexOf('series') !== -1 ? 'tv' : 'movie') + '/week';
        var d = await tmdbFetch(path, { page: page });
        return (d.results || []).map(function (r) { return mapTmdbItem(r, mt); });
      }
      var path2 = mt === 'tv' ? '/discover/tv' : '/discover/movie';
      var d2 = await tmdbFetch(path2, { page: page, sort_by: 'popularity.desc' });
      return (d2.results || []).map(function (r) { return mapTmdbItem(r, mt); });
    }
  }

  // Fallback mínimo: popular del tipo preferido
  var fb = preferTv && !preferMovie ? '/tv/popular' : '/movie/popular';
  var df = await tmdbFetch(fb, { page: page });
  return (df.results || []).map(function (r) { return mapTmdbItem(r, preferTv && !preferMovie ? 'tv' : 'movie'); });
}

async function getCatalog(catalogId, opts) {
  opts = opts || {};
  var page = parseInt(opts.page || 1, 10) || 1;
  var cid = String(catalogId || '').trim();

  // Sesión → catálogos de esa sesión
  if (cid.indexOf('section:') === 0 || cid.indexOf('section/') === 0) {
    var secKey = cid.replace(/^section[:\/]/i, '');
    var sections = loadCatalogs();
    var items = [];
    for (var i = 0; i < sections.length; i++) {
      var sec = sections[i];
      var stitle = (sec.title || '').replace(/\u200e/g, '').trim();
      if (String(sec.id) === secKey || stitle === secKey ||
          String(sec.id).toLowerCase() === secKey.toLowerCase() ||
          stitle.toLowerCase() === secKey.toLowerCase()) {
        (sec.folders || []).forEach(function (folder) {
          items.push({
            id: String(folder.id || folder.title),
            title: folder.title,
            name: folder.title,
            type: 'catalog',
            poster: folder.cover || null,
            backdrop: folder.cover || null,
            catalogId: String(folder.id || folder.title)
          });
        });
        break;
      }
    }
    return { items: items, metas: items, results: items, page: 1, totalPages: 1, hasMore: false };
  }

  var found = findFolder(cid);
  var folder = found.folder;
  if (!folder) {
    return { items: [], metas: [], results: [], page: page, totalPages: 1, hasMore: false, error: 'Catálogo no encontrado' };
  }
  folder._section = (found.sectionTitle || '').replace(/\u200e/g, '').trim();

  var allItems = [];
  try {
    allItems = await fetchCatalogContent(folder, page) || [];
  } catch (e) {
    return { items: [], metas: [], results: [], page: page, totalPages: 1, hasMore: false, error: String(e) };
  }

  return {
    items: allItems,
    metas: allItems,
    results: allItems,
    page: page,
    totalPages: allItems.length >= 20 ? page + 1 : page,
    hasMore: allItems.length >= 20,
    catalogId: cid,
    title: folder.title
  };
}

/**
 * Discover:
 * - Filtros: sesiones (como home) y catálogos de cada sesión
 * - Resultados: el mismo contenido que el catálogo individual
 * No obliga a 3 selects; la app muestra los filtros que devolvemos.
 */
async function getDiscover(opts) {
  opts = opts || {};
  var page = parseInt(opts.page || 1, 10) || 1;
  var filter = (opts.filter || opts.genre || opts.type || opts.catalog || opts.session || '').toString().trim();

  // Si hay filtro de catálogo o sesión → contenido de ese catálogo / lista de catálogos
  if (filter && filter !== 'all' && filter !== 'todo') {
    return getCatalog(filter, { page: page });
  }

  // Sin filtro: no mezclar resultados basura; devolver vacío de items
  // (la UI debe usar filtros: sesión → catálogo → resultados)
  return { items: [], metas: [], results: [], page: 1, totalPages: 1, hasMore: false };
}

async function getDiscoverFilters() {
  // Sesiones primero, luego catálogos (sin Streaming)
  var filters = [];
  var sections = loadCatalogs();
  var enabled = enabledSections();
  var hidden = hiddenCatalogs();
  var skipSections = { 'streaming services': true, 'streaming': true }; // Premios, Productoras, Genres TV activos

  // Grupo 1: sesiones
  for (var i = 0; i < sections.length; i++) {
    var sec = sections[i];
    var stitle = (sec.title || '').replace(/\u200e/g, '').trim();
    var st = stitle.toLowerCase();
    if (skipSections[st]) continue;
    if (enabled.length && enabled.indexOf(st) === -1) continue;
    filters.push({
      id: 'section:' + String(sec.id || stitle),
      title: stitle,
      group: 'session'
    });
  }

  // Grupo 2: catálogos por sesión
  for (var i = 0; i < sections.length; i++) {
    var sec = sections[i];
    var stitle = (sec.title || '').replace(/\u200e/g, '').trim();
    var st = stitle.toLowerCase();
    if (skipSections[st]) continue;
    if (enabled.length && enabled.indexOf(st) === -1) continue;
    (sec.folders || []).forEach(function (folder) {
      var t = (folder.title || '').toLowerCase();
      var id = (folder.id || '').toLowerCase();
      for (var h = 0; h < hidden.length; h++) {
        if (t.indexOf(hidden[h]) !== -1 || id.indexOf(hidden[h]) !== -1) return;
      }
      filters.push({
        id: String(folder.id || folder.title),
        title: folder.title,
        group: stitle,
        parent: 'section:' + String(sec.id || stitle)
      });
    });
  }

  return filters;
}


// ─── Meta: SOLO TMDB (+ OMDB imdb→tmdb) ────────────────────────────────────
async function omdbToTmdb(imdbId) {
  if (!imdbId) return null;
  var id = String(imdbId).indexOf('tt') === 0 ? imdbId : 'tt' + imdbId;
  for (var i = 0; i < OMDB_KEYS.length; i++) {
    try {
      var res = await fetch('https://www.omdbapi.com/?i=' + encodeURIComponent(id) + '&apikey=' + OMDB_KEYS[i]);
      var data = await res.json();
      if (data && data.Response === 'True' && data.imdbID) {
        var find = await tmdbFetch('/find/' + data.imdbID, { external_source: 'imdb_id' });
        var movie = (find.movie_results || [])[0];
        var tv = (find.tv_results || [])[0];
        if (movie) return { tmdbId: String(movie.id), type: 'movie' };
        if (tv) return { tmdbId: String(tv.id), type: 'tv' };
      }
    } catch (e) {}
  }
  return null;
}

async function getMeta(id, type) {
  var parsed = parseContentId(id);
  var tmdbId = parsed.tmdbId;
  var mediaType = parsed.mediaType;
  if (type === 'series' || type === 'tv' || type === 'show') mediaType = 'tv';
  else if (type === 'movie') mediaType = 'movie';

  if (String(tmdbId).indexOf('tt') === 0 || String(id).indexOf('tt') === 0) {
    var conv = await omdbToTmdb(String(id).indexOf('tt') === 0 ? id : tmdbId);
    if (conv) { tmdbId = conv.tmdbId; mediaType = conv.type === 'tv' ? 'tv' : 'movie'; }
  }

  async function fetchMeta(mt) {
    return tmdbFetch('/' + mt + '/' + tmdbId, { append_to_response: 'credits,external_ids,videos,images' });
  }

  var data = null;
  try { data = await fetchMeta(mediaType); }
  catch (e1) {
    try {
      var other = mediaType === 'tv' ? 'movie' : 'tv';
      data = await fetchMeta(other);
      mediaType = other;
    } catch (e2) {
      return { id: String(id), title: 'No encontrado', overview: String(e1), type: mediaType };
    }
  }

  var isTv = mediaType === 'tv';
  var title = data.title || data.name || 'Sin título';
  var year = ((data.release_date || data.first_air_date || '') + '').slice(0, 4);
  var genres = (data.genres || []).map(function (g) { return g.name; });
  var imdb = (data.external_ids && data.external_ids.imdb_id) || null;

  var logo = null;
  try {
    var logos = ((data.images && data.images.logos) || []).filter(function (l) { return l.file_path; });
    logos.sort(function (a, b) {
      var sa = (a.iso_639_1 === 'es' ? 10 : a.iso_639_1 === 'en' ? 5 : 0) + (a.aspect_ratio >= 1.5 && a.aspect_ratio <= 4 ? 3 : 0);
      var sb = (b.iso_639_1 === 'es' ? 10 : b.iso_639_1 === 'en' ? 5 : 0) + (b.aspect_ratio >= 1.5 && b.aspect_ratio <= 4 ? 3 : 0);
      return sb - sa;
    });
    if (logos.length) logo = posterUrl(logos[0].file_path, 'w500');
  } catch (e) {}

  var seasons = [];
  if (isTv && data.seasons) {
    seasons = data.seasons.filter(function (s) { return s.season_number > 0; }).map(function (s) {
      return {
        season: s.season_number, number: s.season_number,
        title: s.name || ('Temporada ' + s.season_number),
        name: s.name || ('Temporada ' + s.season_number),
        episodeCount: s.episode_count, poster: posterUrl(s.poster_path),
        overview: s.overview || '', episodes: []
      };
    });
    var toFetch = seasons.slice(0, 5);
    await Promise.all(toFetch.map(async function (sObj) {
      try {
        var seasonData = await tmdbFetch('/tv/' + tmdbId + '/season/' + sObj.season);
        sObj.episodes = (seasonData.episodes || []).map(function (ep) {
          return {
            episode: ep.episode_number, number: ep.episode_number,
            id: 'tv:' + tmdbId,
            title: ep.name || ('Episodio ' + ep.episode_number),
            name: ep.name || ('Episodio ' + ep.episode_number),
            overview: ep.overview || '',
            still: posterUrl(ep.still_path, 'w300'),
            backdrop: posterUrl(ep.still_path, 'w780'),
            runtime: ep.runtime || null, airDate: ep.air_date || null, rating: ep.vote_average || null
          };
        });
        sObj.episodeCount = sObj.episodes.length || sObj.episodeCount;
      } catch (e) {}
    }));
  }

  return {
    id: mediaType + ':' + String(tmdbId),
    tmdbId: String(tmdbId),
    imdbId: imdb,
    title: title, name: title,
    poster: posterUrl(data.poster_path, 'w500'),
    backdrop: backdropUrl(data.backdrop_path, 'w1280'),
    logo: logo,
    overview: data.overview || '',
    description: data.overview || '',
    type: mediaType,
    media_type: mediaType,
    rating: data.vote_average,
    year: year,
    genres: genres,
    seasons: seasons,
    runtime: data.runtime || (data.episode_run_time && data.episode_run_time[0]) || null,
    status: data.status,
    extra: { logo: logo }
  };
}

async function search(query) {
  if (!query || !String(query).trim()) return { items: [] };
  try {
    var data = await tmdbFetch('/search/multi', { query: String(query).trim() });
    var items = (data.results || []).filter(function (r) {
      return r.media_type === 'movie' || r.media_type === 'tv';
    }).map(function (r) { return mapTmdbItem(r, r.media_type); });
    return { items: items, metas: items, results: items };
  } catch (e) {
    return { items: [] };
  }
}

// ─── Scrapers REALES embebidos (código original de sources/) ───────────────
var __loadedExtractors = {};

function loadExtractor(name) {
  if (__loadedExtractors[name]) return __loadedExtractors[name];
  var code = (typeof __EXTRACTOR_SOURCES !== 'undefined' && __EXTRACTOR_SOURCES) ? __EXTRACTOR_SOURCES[name] : null;
  if (!code) return null;
  try {
    var module = { exports: {} };
    var exports = module.exports;
    // Ejecutar el código del extractor en este scope (usa module.exports)
    var fn = new Function('module', 'exports', code + '\n;return module.exports;');
    var exp = fn(module, exports);
    var getStreamsFn = null;
    if (exp && typeof exp.getStreams === 'function') getStreamsFn = exp.getStreams;
    else if (typeof module.exports.getStreams === 'function') getStreamsFn = module.exports.getStreams;
    else if (typeof module.exports === 'function') getStreamsFn = module.exports;
    __loadedExtractors[name] = getStreamsFn;
    return getStreamsFn;
  } catch (e) {
    console.log('[extractor] load error ' + name + ': ' + e.message);
    __loadedExtractors[name] = null;
    return null;
  }
}

function normalizeStream(s, sourceName) {
  if (!s) return null;
  var url = (s.url || s.file || s.src || s.link || s.stream || '').toString().trim();
  if (!url || url.indexOf('http') !== 0) return null;
  var lower = url.toLowerCase();
  return {
    name: s.name || sourceName,
    title: s.title || s.name || sourceName,
    url: url,
    quality: s.quality || s.q || 'HD',
    language: s.language || s.lang || s.Audio || 'Latino',
    server: s.server || s.serverLabel || sourceName,
    headers: s.headers || null,
    isHls: /\.m3u8|hls|manifest/i.test(lower),
    isMp4: /\.mp4/i.test(lower),
    source: sourceName
  };
}

async function getStreams(id, type, season, episode) {
  var parsed = parseContentId(id);
  var tmdbId = parsed.tmdbId;
  var mediaType = parsed.mediaType;
  if (type === 'series' || type === 'tv' || type === 'show') mediaType = 'tv';
  else if (type === 'movie') mediaType = 'movie';

  // Aceptar objeto como primer arg (algunos players)
  if (id && typeof id === 'object') {
    tmdbId = String(id.tmdbId || id.id || tmdbId);
    mediaType = (id.type === 'tv' || id.type === 'series') ? 'tv' : (id.type === 'movie' ? 'movie' : mediaType);
    season = id.season != null ? id.season : season;
    episode = id.episode != null ? id.episode : episode;
  }

  if (String(tmdbId).indexOf('tt') === 0) {
    var conv = await omdbToTmdb(tmdbId);
    if (conv) { tmdbId = conv.tmdbId; mediaType = conv.type === 'tv' ? 'tv' : 'movie'; }
  }

  var enabled = getEnabledSources();
  var limit = getMaxConcurrent();
  var names = ['embed69', 'vimeus', 'lamovie', 'elifilms', 'homecine'].filter(function (n) {
    return enabled.indexOf(n) !== -1;
  });

  var allStreams = [];
  var seen = {};

  // Ejecutar con límite de concurrencia
  var queue = names.slice();
  async function worker() {
    while (queue.length) {
      var name = queue.shift();
      try {
        var fn = loadExtractor(name);
        if (!fn) continue;
        // Firma típica: getStreams(tmdbId, mediaType, season, episode)
        var raw = await Promise.race([
          Promise.resolve(fn.call(null, String(tmdbId), mediaType, season || null, episode || null)),
          new Promise(function (_, rej) { setTimeout(function () { rej(new Error('timeout')); }, 20000); })
        ]);
        var list = Array.isArray(raw) ? raw : (raw && raw.streams) || [];
        for (var i = 0; i < list.length; i++) {
          var ns = normalizeStream(list[i], name);
          if (!ns) continue;
          var key = ns.url.split('?')[0];
          if (seen[key]) continue;
          seen[key] = true;
          allStreams.push(ns);
        }
      } catch (e) {
        console.log('[getStreams] ' + name + ' error: ' + (e && e.message ? e.message : e));
      }
    }
  }

  var workers = [];
  for (var w = 0; w < Math.min(limit, names.length); w++) workers.push(worker());
  await Promise.all(workers);

  allStreams.sort(function (a, b) {
    if (a.isHls && !b.isHls) return -1;
    if (!a.isHls && b.isHls) return 1;
    return 0;
  });

  return allStreams;
}

var addon = {
  getHome: getHome,
  getCatalogs: getCatalogs,
  getCatalog: getCatalog,
  getDiscover: getDiscover,
  getDiscoverFilters: getDiscoverFilters,
  getMeta: getMeta,
  search: search,
  getStreams: getStreams
};
if (typeof module !== 'undefined' && module.exports) module.exports = addon;
if (typeof globalThis !== 'undefined') {
  globalThis.getHome = getHome;
  globalThis.getCatalogs = getCatalogs;
  globalThis.getCatalog = getCatalog;
  globalThis.getDiscover = getDiscover;
  globalThis.getDiscoverFilters = getDiscoverFilters;
  globalThis.getMeta = getMeta;
  globalThis.search = search;
  globalThis.getStreams = getStreams;
}
